import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { eq, and } from "drizzle-orm";
import path from "node:path";
import fs from "node:fs";
import { v4 as uuid } from "uuid";
import bcrypt from "bcryptjs";
import * as schema from "../src/lib/db/schema";

const dbFile = process.env.DATABASE_URL ?? "data/dev.sqlite";
const absPath = path.isAbsolute(dbFile)
  ? dbFile
  : path.join(process.cwd(), dbFile);
fs.mkdirSync(path.dirname(absPath), { recursive: true });

const sqlite = new Database(absPath);
sqlite.pragma("journal_mode = WAL");
sqlite.pragma("foreign_keys = ON");
const db = drizzle(sqlite, { schema });

const { subjects, topics, questions, users } = schema;

async function upsertSubject(slug: string, nameZh: string, orderIdx: number, status: "active" | "draft") {
  const existing = await db.query.subjects.findFirst({ where: eq(subjects.slug, slug) });
  if (existing) return existing;
  const id = uuid();
  await db.insert(subjects).values({ id, slug, nameZh, orderIdx, status });
  const row = await db.query.subjects.findFirst({ where: eq(subjects.slug, slug) });
  return row!;
}

async function upsertTopic(
  subjectId: string,
  slug: string,
  nameZh: string,
  orderIdx: number,
  description: string
) {
  const existing = await db.query.topics.findFirst({
    where: and(eq(topics.subjectId, subjectId), eq(topics.slug, slug)),
  });
  if (existing) return existing;
  const id = uuid();
  await db.insert(topics).values({
    id,
    subjectId,
    slug,
    nameZh,
    orderIdx,
    description,
  });
  return (await db.query.topics.findFirst({
    where: and(eq(topics.subjectId, subjectId), eq(topics.slug, slug)),
  }))!;
}

interface QSeed {
  topicSlug: string;
  type: "choice" | "multi" | "essay";
  questionMd: string;
  options?: { key: string; text: string }[];
  correctAnswer?: string | string[];
  explanationMd: string;
  references: { label: string; url: string }[];
  difficulty: number;
  source?: string;
}

async function upsertQuestion(topicId: string, q: QSeed) {
  // 用 question_md hash 做 dedupe key —— 簡單版直接查同 topic + 同 question_md
  const existing = await db.query.questions.findFirst({
    where: and(eq(questions.topicId, topicId), eq(questions.questionMd, q.questionMd)),
  });
  if (existing) return existing;
  await db.insert(questions).values({
    id: uuid(),
    topicId,
    type: q.type,
    questionMd: q.questionMd,
    optionsJson: q.options ? JSON.stringify(q.options) : null,
    correctAnswerJson: q.correctAnswer ? JSON.stringify(q.correctAnswer) : null,
    explanationMd: q.explanationMd,
    referencesJson: JSON.stringify(q.references),
    difficulty: q.difficulty,
    source: q.source ?? null,
    status: "published",
  });
}

