        "**民法第 106 條**：「代理人非經本人之許諾，不得為本人與自己之法律行為，亦不得既為第三人之代理人，而為本人與第三人之法律行為。但其法律行為，係專履行債務者，不在此限。」\n\n- **D 對**：自己代理 / 雙方代理之禁止屬避免利益衝突；違反 §106 通說採「效力未定」見解，類推 §170 須經本人承認；非絕對無效。\n- A 錯：§106 明文禁止。\n- B 錯：詐欺須有故意施詐之要件；§106 禁止性規定不論主觀有無詐欺意圖。\n- C 錯：忽略本人甲之拒絕承認權。",
