      correctAnswer: "B",
      explanationMd:
        "**民法第 255 條**：「依契約之性質或當事人之意思表示，非於一定時期為給付不能達其契約之目的，而契約當事人之一方不按照時期給付者，他方當事人得不為前條（§254）之催告，解除其契約。」\n\n- **B 對**：婚紗、結婚蛋糕、跨年表演票、選舉宣傳印刷等「過期即失意義」之契約屬 §255 定期行為，債權人得不必先催告即可解除。\n- A 錯：§255 為 §254 之例外，定期行為不必催告。\n- C 錯：定期行為過期即失意義，債權人有解除權保護其契約利益。\n- D 錯：解除權之行使為意思表示即可（§258），不必訴請法院。",
