      explanationMd:
        "**民法第 819 條**：「各共有人，得自由處分其應有部分。共有物之處分、變更，及設定負擔，應得共有人全體之同意。」\n**民法第 820 條第 1 項**：「共有物之管理，除契約另有約定外，應以共有人過半數及其應有部分合計過半數之同意行之。但其應有部分合計逾 2/3 者，其人數不予計算。」\n**土地法第 34 條之 1**：共有土地之處分得以多數決行之（§820 / §828 之特別規定）。\n\n- **A 對**：完整闡釋分別共有處分自己份額（§819 I）vs. 處分整塊（§819 II）vs. 管理（§820）之三種規則。\n- B 錯：§819 I 自由處分自己之應有部分。\n- C 錯：§820 為「管理」（不變更物權狀態）之多數決，「處分」整塊仍依 §819 II 全體同意（或土地法 §34-1 特別規定）。\n- D 錯：分別共有為共有所有權，非各自獨立所有權。",
