      questionMd:
        "依民法第 1223 條，被繼承人之直系血親卑親屬之特留分為其應繼分之多少？",
      options: [
        { key: "A", text: "三分之一（與兄弟姊妹、祖父母同列低比例特留分）。" },
        { key: "B", text: "三分之二（誤將特留分與應繼分之關係顛倒計算）。" },
        { key: "C", text: "四分之一（誤套外國立法例非我國 §1223 之規定）。" },
        { key: "D", text: "二分之一（與父母、配偶同列高比例特留分群組）。" },
      ],
      correctAnswer: "D",
      explanationMd:
        "**民法第 1223 條**：「繼承人之特留分，依下列各款之規定：\n一、直系血親卑親屬之特留分，為其應繼分二分之一。\n二、父母之特留分，為其應繼分二分之一。\n三、配偶之特留分，為其應繼分二分之一。\n四、兄弟姊妹之特留分，為其應繼分三分之一。\n五、祖父母之特留分，為其應繼分三分之一。」\n\n直系血親卑親屬、父母、配偶皆為應繼分二分之一；兄弟姊妹、祖父母為三分之一。",
