      correctAnswer: "A",
      explanationMd:
        "**民法第 11 條**：「二人以上同時遇難，不能證明其死亡之先後時，推定為同時死亡。」 — 同時死亡者互不繼承（須對方活著始能繼承）。\n\n**§1140 之適用爭議**（學說兩派）：\n- **代位繼承說（通說 / 多數說）**：將「同時死亡」目的性擴張包含於 §1140「繼承開始前死亡」之構成要件，孫得代位。法理為保護下一代權益，避免「技術性同時」剝奪原本應得之份額。\n- **固有權說（少數說）**：認代位繼承須父輩於繼承開始前已死亡，同時死亡時孫無代位權，遺產歸同順位繼承人。\n\n台灣學說多數採代位繼承說（見王澤鑑《民法繼承編》、林秀雄《繼承法講義》等）；實務見解亦多傾向保護孫輩。\n\n- **A 對**：依通說（代位繼承說），C 代位 A 取得 600 萬，B 直接繼承 600 萬。\n- B 錯：採少數固有權說之結論，非通說。\n- C 錯：有繼承人時遺產不歸國家。\n- D 錯：§11 推定同時死亡 → 互不繼承。",
