        "**民法第 1 條**：「民事，法律所未規定者，依習慣；無習慣者，依法理。」\n**民法第 2 條**：「習慣不得違反公共秩序或善良風俗。」\n\n法源搜索順位：\n1. **法律**（含類推適用）。\n2. **習慣**（須通過 §2 公序良俗審查）。\n3. **法理**（含憲法精神、學說、判例、國際法源 CISG / PECL / PETL / PICC）。\n\n- **D 對**：完整闡釋 §1 法源順位。\n- A 錯：法官造法限於「填補法律漏洞」（類推適用），非無條件創造新法律。\n- B 錯：依 §1 文義，習慣優先於法理。\n- C 錯：法律未規定不等於無理由；法官須依 §1 順位搜索法源。",
